update public.quests set requirements=jsonb_set(requirements, '{mystery,release_status}', '"client_playable_pending_release"'::jsonb, false) where id in ('mq_unlisted_two_chairs', 'mq_unlisted_second_number', 'mq_unlisted_obedient_lock', 'mq_unlisted_folded_route', 'mq_unlisted_right_to_remain', 'mq_muster_fourth_beat', 'mq_muster_boots_outward', 'mq_muster_cable_thief', 'mq_muster_shared_shift', 'mq_muster_warning_not_oath', 'mq_zero_weight_nothing', 'mq_zero_inside_label', 'mq_zero_fee_at_door', 'mq_zero_rent_inside_rent', 'mq_zero_port_without_lie', 'mq_quiet_cloth_on_crystal', 'mq_quiet_bench_wrong_way', 'mq_quiet_test_without_beast', 'mq_quiet_same_pause', 'mq_quiet_silence_kept', 'mq_armistice_modern_lock', 'mq_armistice_burn_without_verdict', 'mq_armistice_safe_for_copy', 'mq_armistice_reserve_not_ransom', 'mq_armistice_unwritten_witness');
do $mystery_activation$
begin
 if (select count(*) from public.quests where id in ('mq_unlisted_two_chairs', 'mq_unlisted_second_number', 'mq_unlisted_obedient_lock', 'mq_unlisted_folded_route', 'mq_unlisted_right_to_remain', 'mq_muster_fourth_beat', 'mq_muster_boots_outward', 'mq_muster_cable_thief', 'mq_muster_shared_shift', 'mq_muster_warning_not_oath', 'mq_zero_weight_nothing', 'mq_zero_inside_label', 'mq_zero_fee_at_door', 'mq_zero_rent_inside_rent', 'mq_zero_port_without_lie', 'mq_quiet_cloth_on_crystal', 'mq_quiet_bench_wrong_way', 'mq_quiet_test_without_beast', 'mq_quiet_same_pause', 'mq_quiet_silence_kept', 'mq_armistice_modern_lock', 'mq_armistice_burn_without_verdict', 'mq_armistice_safe_for_copy', 'mq_armistice_reserve_not_ransom', 'mq_armistice_unwritten_witness') and requirements->'mystery'->>'release_status'='client_playable_pending_release') <> 25 then raise exception 'Mystery metadata missing'; end if;
 if (select count(*) from public.achievements where id in ('mq_achievement_unlisted_two_chairs', 'mq_achievement_unlisted_second_number', 'mq_achievement_unlisted_obedient_lock', 'mq_achievement_unlisted_folded_route', 'mq_achievement_unlisted_right_to_remain', 'mq_achievement_muster_fourth_beat', 'mq_achievement_muster_boots_outward', 'mq_achievement_muster_cable_thief', 'mq_achievement_muster_shared_shift', 'mq_achievement_muster_warning_not_oath', 'mq_achievement_zero_weight_nothing', 'mq_achievement_zero_inside_label', 'mq_achievement_zero_fee_at_door', 'mq_achievement_zero_rent_inside_rent', 'mq_achievement_zero_port_without_lie', 'mq_achievement_quiet_cloth_on_crystal', 'mq_achievement_quiet_bench_wrong_way', 'mq_achievement_quiet_test_without_beast', 'mq_achievement_quiet_same_pause', 'mq_achievement_quiet_silence_kept', 'mq_achievement_armistice_modern_lock', 'mq_achievement_armistice_burn_without_verdict', 'mq_achievement_armistice_safe_for_copy', 'mq_achievement_armistice_reserve_not_ransom', 'mq_achievement_armistice_unwritten_witness')) <> 25 then raise exception 'Mystery achievements missing'; end if;
 if exists (select 1 from public.achievements a left join public.quests q on q.id=replace(a.metric, 'mystery_completed.', '') where a.id in ('mq_achievement_unlisted_two_chairs', 'mq_achievement_unlisted_second_number', 'mq_achievement_unlisted_obedient_lock', 'mq_achievement_unlisted_folded_route', 'mq_achievement_unlisted_right_to_remain', 'mq_achievement_muster_fourth_beat', 'mq_achievement_muster_boots_outward', 'mq_achievement_muster_cable_thief', 'mq_achievement_muster_shared_shift', 'mq_achievement_muster_warning_not_oath', 'mq_achievement_zero_weight_nothing', 'mq_achievement_zero_inside_label', 'mq_achievement_zero_fee_at_door', 'mq_achievement_zero_rent_inside_rent', 'mq_achievement_zero_port_without_lie', 'mq_achievement_quiet_cloth_on_crystal', 'mq_achievement_quiet_bench_wrong_way', 'mq_achievement_quiet_test_without_beast', 'mq_achievement_quiet_same_pause', 'mq_achievement_quiet_silence_kept', 'mq_achievement_armistice_modern_lock', 'mq_achievement_armistice_burn_without_verdict', 'mq_achievement_armistice_safe_for_copy', 'mq_achievement_armistice_reserve_not_ransom', 'mq_achievement_armistice_unwritten_witness') and (q.id is null or a.reward_rubies<>0 or not a.hidden or a.threshold<>1)) then raise exception 'Invalid mystery achievement'; end if;
end;
$mystery_activation$;
commit;
